import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxSelect,
  JxButton,
  JxDivider,
  JxBadge,
} from '@jinx-ui/react';

export interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  address: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'pl', label: 'Польша' },
  { value: 'de', label: 'Германия' },
  { value: 'kz', label: 'Казахстан' },
];

export default function RegistrationWizard({ onSubmit }: { onSubmit: (data: RegistrationData) => void }) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({
    name: '',
    email: '',
    phone: '',
    country: '',
    city: '',
    address: '',
  });

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const emailError =
    data.email.length > 0 && !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const contactsReady = data.name.trim() !== '' && data.email.includes('@');
  const addressReady = data.country !== '' && data.city.trim() !== '' && data.address.trim() !== '';
  const canGoNext = step === 0 ? contactsReady : addressReady;

  const isLast = step === steps.length - 1;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', fontFamily: 'var(--jx-font-sans)' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
            placeholder="Иван Петров"
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={emailError}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={(event) => set('phone', event.target.value)}
            helperText="Необязательно"
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={(value) => set('country', value)}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
          />
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={data.address}
            onChange={(event) => set('address', event.target.value)}
            helperText="Улица, дом, квартира, индекс"
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxDivider label="Контакты" />
          <SummaryRow label="Имя" value={data.name} />
          <SummaryRow label="Почта" value={data.email} />
          <SummaryRow label="Телефон" value={data.phone ? `+7${data.phone}` : ''} />
          <JxDivider label="Адрес" />
          <SummaryRow
            label="Страна"
            value={countries.find((country) => country.value === data.country)?.label ?? ''}
          />
          <SummaryRow label="Город" value={data.city} />
          <SummaryRow label="Адрес" value={data.address} />
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={() => setStep(step - 1)}>
          Назад
        </JxButton>
        {isLast ? (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" disabled={!canGoNext} onClick={() => setStep(step + 1)}>
            Дальше
          </JxButton>
        )}
      </div>
    </div>
  );
}

function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px', justifyContent: 'space-between' }}>
      <span style={{ color: 'var(--jx-text-3)' }}>{label}</span>
      {value ? (
        <span style={{ color: 'var(--jx-text)' }}>{value}</span>
      ) : (
        <JxBadge tone="warning">Не указано</JxBadge>
      )}
    </div>
  );
}

